def quirk_hint(qid: str) -> str:
    """Hint shown while the quirk is locked ('' if none)."""
    return QUIRK_HINT.get(qid, '')


def quirk_description(qid: str) -> str:
    """Explanation shown once the quirk is unlocked ('' if none)."""
    return QUIRK_DESC.get(qid, '')
